package gen:node;

world node {
    use aap:caps/types@0.1.0.{feed-item, classification, classified-item, dropped-item, category, importance};

    import aap:caps/inference-llm@0.1.0;

    export run: func(item: feed-item) -> classification;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::inference_llm::infer;

struct Node;

impl Guest for Node {
    fn run(item: FeedItem) -> Classification {
        let system = "You are a feed triage classifier. Given an item's title and text, \
                       respond with exactly one category word (release, security, research, \
                       tooling, discussion, other) followed by exactly one importance word \
                       (must-read, worth-a-look, skip), separated by a space. Example: \
                       'security must-read'.";
        let prompt = format!(
            "Title: {}\nFeed: {}\nText: {}",
            item.title, item.feed, item.text
        );

        let response = infer(system, &prompt, "classify");

        let mut parts = response.split_whitespace();
        let category = match parts.next().unwrap_or("").to_lowercase().as_str() {
            "release" => Category::Release,
            "security" => Category::Security,
            "research" => Category::Research,
            "tooling" => Category::Tooling,
            "discussion" => Category::Discussion,
            _ => Category::Other,
        };
        let importance = match parts.next().unwrap_or("").to_lowercase().as_str() {
            "must-read" => Importance::MustRead,
            "worth-a-look" => Importance::WorthALook,
            _ => Importance::Skip,
        };

        if matches!(importance, Importance::Skip) {
            Classification::Drop(DroppedItem { item, category })
        } else {
            Classification::Keep(ClassifiedItem {
                item,
                category,
                importance,
            })
        }
    }
}

export!(Node);
```

